$filter = static fn (string $key): string => (string) ($filters[$key] ?? '');
$datePreset = (string) ($filters['date_range'] ?? '');
if (!in_array($datePreset, ['last7', 'last30', 'custom'], true)) $datePreset = $filter('start_date') !== '' || $filter('end_date') !== '' ? 'custom' : '';
$auditSummary = $auditSummary ?? ['total' => count($events), 'today' => 0, 'successful' => 0, 'failed' => 0];
$relativeAuditTime = static function (string $value): string {
    $seconds = max(0, time() - strtotime($value . ' UTC'));
    if ($seconds < 60) return 'Just now';
    if ($seconds < 3600) return (int) floor($seconds / 60) . ' min ago';
    if ($seconds < 86400) return (int) floor($seconds / 3600) . ' hr ago';
    if ($seconds < 2592000) return (int) floor($seconds / 86400) . ' days ago';
    return date('M j, Y', strtotime($value . ' UTC'));
};
